void startRentFlowFixed() { WidgetsFlutterBinding.ensureInitialized(); runApp(const RentFlowApp()); }
class RentFlowApp extends StatelessWidget { const RentFlowApp({super.key}); @override Widget build(BuildContext c) => MaterialApp(debugShowCheckedModeBanner:false,title:'RentFlow',theme:ThemeData(useMaterial3:true,scaffoldBackgroundColor:pageBg,colorScheme:ColorScheme.fromSeed(seedColor:emerald),appBarTheme:const AppBarTheme(backgroundColor:Colors.white,foregroundColor:ink,elevation:0),inputDecorationTheme:const InputDecorationTheme(filled:true,fillColor:Colors.white)),home:const HomePage()); }

class RentDB extends ChangeNotifier {
  SharedPreferences? prefs; List<Map<String,dynamic>> shops=[]; int active=0;
  bool get ready=>prefs!=null; Map<String,dynamic> get shop=>shops.isEmpty?<String,dynamic>{}:shops[active];
  Future<void> load() async { prefs=await SharedPreferences.getInstance(); try{final r=jsonDecode(prefs!.getString('rentflow_data')??'[]');if(r is List)shops=r.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();}catch(_){shops=[];} active=prefs!.getInt('rentflow_active')??0;if(active<0||active>=shops.length)active=0;notifyListeners(); }
  Future<void> save() async {await prefs?.setString('rentflow_data',jsonEncode(shops));await prefs?.setInt('rentflow_active',active);notifyListeners();}
  List<Map<String,dynamic>> records(String k){final v=shop[k];if(v is! List)return[];return v.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();}
  Future<void> addShop(Map<String,dynamic>d)async{shops.add({...d,'items':[],'customers':[],'issues':[],'returns':[]});active=shops.length-1;await save();}
  Future<void> updateShop(Map<String,dynamic>d)async{shop.addAll(d);await save();}
  Future<void> addRecord(String k,Map<String,dynamic>d)async{if(shop[k] is! List)shop[k]=[];(shop[k] as List).add(d);await save();}
  Future<void> editRecord(String k,int i,Map<String,dynamic>d)async{(shop[k] as List)[i]=d;await save();}
  Future<void> stock(String id,int delta)async{final a=shop['items'] as List? ?? [];for(var i=0;i<a.length;i++){final x=Map<String,dynamic>.from(a[i] as Map);if('${x['id']}'==id){x['quantity']=(int.tryParse('${x['quantity']??0}')??0)+delta;if((x['quantity'] as int)<0)x['quantity']=0;a[i]=x;break;}}await save();}
}
final db=RentDB();
String uid()=>DateTime.now().microsecondsSinceEpoch.toString(); String today()=>DateTime.now().toIso8601String().substring(0,10); String money(dynamic v)=>'₹${(double.tryParse('$v')??0).toStringAsFixed(2)}';
List<Map<String,dynamic>> maps(dynamic v)=>v is List?v.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList():[];
int daysBetween(String a,String b){final x=DateTime.tryParse(a)??DateTime.now();final y=DateTime.tryParse(b)??DateTime.now();final d=y.difference(x).inDays;return d<1?1:d;}
void openPage(BuildContext c,Widget p)=>Navigator.push(c,MaterialPageRoute(builder:(_)=>p));

