class _ReturnState extends State<ReturnPage>{String? customer;Map<String,dynamic>? issue;final selected=<String,int>{};final manual=TextEditingController();final notes=TextEditingController();@override void dispose(){manual.dispose();notes.dispose();super.dispose();}Future<void>save()async{if(issue==null)return;final rd=today();final out=<Map<String,dynamic>>[];double total=0;final d=daysBetween('${issue!['issueDate']}',rd);for(final x in maps(issue!['items'])){final q=selected['${x['itemId']}']??0;if(q<=0)continue;final r=double.tryParse('${x['rentPrice']??15}')??15;final line=r*q*d/100;total+=line;out.add({'itemId':x['itemId'],'name':x['name'],'issuedQty':x['qty'],'returnQty':q,'rentPrice':r,'rentDays':d,'amount':line});await db.stock('${x['itemId']}',q);}if(out.isEmpty)return;final manualAmount=double.tryParse(manual.text);if(manualAmount!=null)total=manualAmount;await db.addRecord('returns',{'id':uid(),'returnInvoice':'RET-${DateTime.now().millisecondsSinceEpoch}','customerId':customer,'issueInvoice':issue!['invoice'],'issueDate':issue!['issueDate'],'returnDate':rd,'rentDays':d,'amount':total,'notes':notes.text.trim(),'items':out});if(mounted)Navigator.pop(context);}@override Widget build(BuildContext c){final customers=db.records('customers'),issues=db.records('issues');final items=issue==null?<Map<String,dynamic>>[]:maps(issue!['items']);return Frame('Return / Receive',Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Row(children:[Expanded(child:DropdownButtonFormField<String>(value:customer,decoration:const InputDecoration(labelText:'Customer / Party'),items:customers.map((x)=>DropdownMenuItem(value:'${x['id']}',child:Text('${x['name']}'))).toList(),onChanged:(v)=>setState((){customer=v;issue=null;selected.clear();}))),IconButton(tooltip:'Add Customer',onPressed:()=>openPage(c,const CustomerForm()),icon:const Icon(Icons.add_circle_rounded,color:emerald,size:32))]),const SizedBox(height:10),DropdownButtonFormField<String>(value:issue?['id']?.toString(),decoration:const InputDecoration(labelText:'Issued Invoice'),items:issues.where((x)=>customer==null||'${x['customerId']}'==customer).map((x)=>DropdownMenuItem(value:'${x['id']}',child:Text('${x['invoice']} • ${x['issueDate']}'))).toList(),onChanged:(v){final x=issues.firstWhere((q)=>'${q['id']}'==v);setState((){issue=x;selected.clear();});}),if(issue!=null)...[const SizedBox(height:10),Text('Issued Date: ${issue!['issueDate']}  •  Return Date: ${today()}',style:const TextStyle(fontWeight:FontWeight.w800)),const SizedBox(height:8),...items.map((x)=>ReturnItem(item:x,issueDate:'${issue!['issueDate']}',qty:selected['${x['itemId']}']??0,onChanged:(q)=>setState(()=>selected['${x['itemId']}']=q))),Field('Manual Return Amount (optional)',manual,type:const TextInputType.numberWithOptions(decimal:true)),Field('Notes',notes,maxLines:3),SaveBtn('Save Return & Receipt',save)]));}}
class ReturnItem extends StatelessWidget{final Map<String,dynamic>item;final String issueDate;final int qty;final ValueChanged<int>onChanged;const ReturnItem({super.key,required this.item,required this.issueDate,required this.qty,required this.onChanged});@override Widget build(BuildContext c){final max=int.tryParse('${item['qty']??0}')??0;final r=double.tryParse('${item['rentPrice']??15}')??15;final d=daysBetween(issueDate,today());return Card(elevation:0,color:qty>0?emeraldSoft:Colors.white,child:Padding(padding:const EdgeInsets.all(12),child:Row(children:[const Icon(Icons.inventory_2_outlined,color:emerald),const SizedBox(width:10),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${item['name']}',style:const TextStyle(fontWeight:FontWeight.w900)),Text('Issued Qty $max • Return Qty $qty'),Text('Rent Price $r/100 • Rent Days $d • Amount ${money(r*qty*d/100)}',style:const TextStyle(color:emeraldDark,fontWeight:FontWeight.w800))])),SizedBox(width:78,child:TextFormField(initialValue:qty==0?'':'$qty',keyboardType:TextInputType.number,decoration:InputDecoration(labelText:'Return',hintText:'0-$max'),onChanged:(v)=>onChanged((int.tryParse(v)??0).clamp(0,max))))])));}}

class InventoryPage extends StatelessWidget{const InventoryPage({super.key});@override Widget build(BuildContext c){final a=db.records('items');return Frame('Inventory Register',Column(children:[if(a.isEmpty)const Empty('No inventory records.'),...a.map((x)=>Card(elevation:0,child:ListTile(title:Text('${x['name']}',style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('Code ${x['code']??''} • Rent ${x['rentPrice']??15}/100'),trailing:Text('${x['quantity']??0}',style:const TextStyle(fontSize:20,fontWeight:FontWeight.w900,color:emerald))))]));}}
String partyName(String? id){for(final x in db.records('customers')){if('${x['id']}'==id)return'${x['name']}';}return'Party';}
class BillsPage extends StatelessWidget{const BillsPage({super.key});@override Widget build(BuildContext c){final issues=db.records('issues'),returns=db.records('returns');return Frame('Reports / Bills',Column(children:[const Align(alignment:Alignment.centerLeft,child:Text('ISSUED BILLS',style:TextStyle(fontWeight:FontWeight.w900,color:emeraldDark))),if(issues.isEmpty)const Empty('No issued bills yet.'),...issues.map((x)=>billTile(c,x,false)),const SizedBox(height:12),const Align(alignment:Alignment.centerLeft,child:Text('RETURN RECEIPTS',style:TextStyle(fontWeight:FontWeight.w900,color:emeraldDark))),if(returns.isEmpty)const Empty('No return receipts yet.'),...returns.map((x)=>billTile(c,x,true))]));}
Widget billTile(BuildContext c,Map<String,dynamic>x,bool ret)=>Card(elevation:0,child:ListTile(leading:Icon(ret?Icons.assignment_return:Icons.receipt_long,color:emerald),title:Text('${x[ret?'returnInvoice':'invoice']} • ${partyName('${x['customerId']}')}',style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text(ret?'Issued ${x['issueDate']} • Return ${x['returnDate']} • Rent Days ${x['rentDays']} • ${money(x['amount'])}':'Issued ${x['issueDate']} • ${maps(x['items']).length} item(s)'),trailing:Wrap(children:[IconButton(tooltip:'Preview / Print PDF',onPressed:()=>pdfPreview(c,x,isReturn:ret),icon:const Icon(Icons.picture_as_pdf,color:emerald)),IconButton(tooltip:'Save / Share PDF',onPressed:()=>pdfShare(x,isReturn:ret),icon:const Icon(Icons.share,color:emerald))]));}
}
Future<pw.Document> makePdf(Map<String,dynamic>x,{bool isReturn=false})async{final doc=pw.Document();final items=maps(x['items']);doc.addPage(pw.MultiPage(pageFormat:pw.PdfPageFormat.a4,build:(_)=>[pw.Text('${db.shop['name']??'RentFlow'}',style:pw.TextStyle(fontSize:22,fontWeight:pw.FontWeight.bold)),pw.Text('${db.shop['address']??''}  ${db.shop['mobile']??''}'),pw.SizedBox(height:10),pw.Text(isReturn?'RETURN RECEIPT':'RENTAL ISSUE INVOICE',style:pw.TextStyle(fontSize:18,fontWeight:pw.FontWeight.bold)),pw.Text('Party: ${partyName('${x['customerId']}')}'),pw.Text('Invoice: ${x[isReturn?'returnInvoice':'invoice']??''}'),pw.Text('Issued Date: ${x['issueDate']??''}'),if(isReturn)pw.Text('Return Date: ${x['returnDate']??''}'),pw.SizedBox(height:12),pw.TableHelper.fromTextArray(headers:isReturn?['Item','Issued Qty','Return Qty','Rent/100','Rent Days','Amount']:['Item','Qty','Rent/100'],data:items.map((i)=>isReturn?['${i['name']}','${i['issuedQty']}','${i['returnQty']}','${i['rentPrice']}','${i['rentDays']}','${money(i['amount'])}']:['${i['name']}','${i['qty']}','${i['rentPrice']}']).toList()),if(isReturn)pw.Padding(padding:const pw.EdgeInsets.only(top:12),child:pw.Text('Total: ${money(x['amount'])}',style:pw.TextStyle(fontSize:16,fontWeight:pw.FontWeight.bold))),pw.SizedBox(height:24),pw.Text('By PaliaAPK HUB • Developer by shanpalia')]);return doc;}
Future<void>pdfPreview(BuildContext c,Map<String,dynamic>x,{bool isReturn=false})async{final doc=await makePdf(x,isReturn:isReturn);if(!c.mounted)return;await Printing.layoutPdf(onLayout:(_)=>doc.save());}
Future<void>pdfShare(Map<String,dynamic>x,{bool isReturn=false})async{final doc=await makePdf(x,isReturn:isReturn);await Printing.sharePdf(bytes:await doc.save(),filename:'${x[isReturn?'returnInvoice':'invoice']??'rentflow'}.pdf');}
class Empty extends StatelessWidget{final String text;const Empty(this.text,{super.key});@override Widget build(BuildContext c)=>Padding(padding:const EdgeInsets.all(24),child:Center(child:Text(text,textAlign:TextAlign.center,style:const TextStyle(color:Colors.black54))));}
class SettingsPage extends StatelessWidget{const SettingsPage({super.key});@override Widget build(BuildContext c)=>Frame('Settings / About',Column(children:[Card(elevation:0,child:ListTile(leading:const Icon(Icons.info_outline,color:emerald),title:const Text('RentFlow',style:TextStyle(fontWeight:FontWeight.w900)),subtitle:const Text('Rental Management • By PaliaAPK HUB • Developer by shanpalia'))),Card(elevation:0,child:ListTile(leading:const Icon(Icons.store_rounded,color:emerald),title:const Text('Shop / Company'),onTap:()=>openPage(c,const ShopPage()))]));}
